const [retryCount, setRetryCount] = useState(0);
const reconnect = useCallback(async () => {
const delay = Math.min(1000 * Math.pow(2, retryCount), 30000);
await new Promise(resolve => setTimeout(resolve, delay));
// Attempt reconnection
}, [retryCount]);
};
